{
  "methodological_details": [
    {
      "The study used 4T1 murine triple negative breast cancer and CT26 colorectal cancer cell lines.": "4T1"
    },
    {
      "Cd274 encoding PD-L1 was deleted using CRISPR-Cas9 in these cell lines.": "lentiCRISPRv2"
    },
    {
      "An in vitro CTL-tumor interaction system using 2/20 tumor-specific CTLs was utilized.": "2/20"
    },
    {
      "2/20 cells recognize the H2-Ld-restricted AH1 epitope of gp70 protein.": "AH1 epitope"
    },
    {
      "In vivo models included orthotopic injection for primary tumors and tail vein injection for metastasis.": "tail vein injection"
    },
    {
      "Lung metastasis was quantified by harvesting lungs and inflating with India ink solution.": "India ink solution"
    },
    {
      "RNA sequencing was performed on lungs colonized by WT and PD-L1-deficient 4T1 cells.": "RNA sequencing"
    },
    {
      "Single-cell RNA sequencing was performed on CD45+ leukocytes from colonized lungs.": "single-cell RNA sequencing"
    },
    {
      "Approximately 7500 cells were analyzed using UMAP for dimensional reduction.": "7500 cells"
    },
    {
      "Flow cytometry was used to validate transcriptomic data in 4T1-colonized lungs.": "flow cytometry"
    },
    {
      "Myeloid cells were depleted using clodronate liposomes in tumor-bearing mice.": "clodronate liposomes"
    },
    {
      "Human patient data from metastatic basal cell carcinoma was analyzed.": "basal cell carcinoma"
    },
    {
      "Statistical analysis was conducted using Prism8 and two-tailed Student's t-test.": "Prism8"
    },
    {
      "Bulk RNA sequencing used STARv2.5 for alignment and DESeq2 for quantification.": "DESeq2"
    },
    {
      "Single-cell libraries were generated using the Chromium Single Cell 3' Reagent Kit v3.": "Chromium Single Cell"
    }
  ],
  "key_results": [
    {
      "tPD-L1 confers no survival advantage when an antigen-specific effector CTL encounters a tumor cell.": "no survival advantage"
    },
    {
      "No difference was observed in primary tumor growth between PD-L1 WT and KO 4T1 cells.": "primary tumor growth"
    },
    {
      "Knocking out PD-L1 in tumor cells significantly decreases lung metastasis.": "decreases lung metastasis"
    },
    {
      "Increased infiltration of CD3+ cells was observed in the lung after loss of tPD-L1.": "CD3+ cells"
    },
    {
      "No difference in initial tumor cell colonization was seen one day after tail vein injection.": "initial tumor cell colonization"
    },
    {
      "PD-L1-deficient and competent 4T1 metastasized equally in RAGII-KO mice.": "RAGII-KO mice"
    },
    {
      "Genetic ablation of MHC class I and CD8+ T cell depletion revealed tPD-L1 drives metastasis.": "MHC class I"
    },
    {
      "Single-cell RNA sequencing revealed tPD-L1 engages myeloid PD-1 to antagonize type I IFN.": "myeloid PD-1"
    },
    {
      "Expression changes were observed in myeloid cells, not CTLs, in the metastatic niche.": "myeloid cells"
    },
    {
      "Enhanced antigen presentation machinery was detected in macrophages following tPD-L1 loss.": "antigen presentation machinery"
